package com.enfec.one.asset.workflow;

import com.enfec.one.asset.audit.*; import com.enfec.one.asset.auth.SessionAuthService; import com.enfec.one.asset.dto.workflow.*; import com.enfec.one.asset.entity.*; import com.enfec.one.asset.notification.*; import com.enfec.one.asset.repository.AssetRepository; import com.enfec.one.asset.service.AssetService; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;

@Service public class WorkflowService {
 private final WorkflowRequestRepository requests; private final WorkflowApprovalRepository approvals; private final AssetReservationRepository reservations; private final PurchaseOrderRepository pos; private final GoodsReceiptRepository grns; private final MaintenanceTicketRepository maintenance; private final AssetRepository assets; private final AssetService assetService; private final SessionAuthService auth; private final NotificationRepository notifications; private final AuditLogRepository audit;
 public WorkflowService(WorkflowRequestRepository r,WorkflowApprovalRepository a,AssetReservationRepository ar,PurchaseOrderRepository p,GoodsReceiptRepository g,MaintenanceTicketRepository m,AssetRepository assets,AssetService as,SessionAuthService auth,NotificationRepository n,AuditLogRepository audit ){this.requests=r;this.approvals=a;this.reservations=ar;this.pos=p;this.grns=g;this.maintenance=m;this.assets=assets;this.assetService=as;this.auth=auth;this.notifications=n;this.audit=audit;}
 public List<WorkflowRequest> all(String s){
  var u=auth.require(s);
  var all=requests.findAllByOrderByCreatedAtDesc();
  return switch(u.role().toUpperCase()){
   case "ADMIN" -> all;
   case "HR" -> all.stream().filter(r -> "ONBOARDING".equals(r.getWorkflowType()) && u.username().equalsIgnoreCase(r.getRequesterUsername())).toList();
   case "VP" -> all.stream().filter(r -> "VP_APPROVAL".equals(r.getStage())).toList();
   case "MANAGER" -> all.stream().filter(r -> "MANAGER_APPROVAL".equals(r.getStage())).toList();
   case "FINANCE" -> all.stream().filter(r -> "FINANCE_BUDGET".equals(r.getStage())).toList();
   case "PROCUREMENT" -> all.stream().filter(r -> "PROCUREMENT".equals(r.getWorkflowType())).toList();
   default -> throw new IllegalArgumentException("Access denied");
  };
 }
 public List<WorkflowRequest> mine(String s){var u=auth.require(s);return requests.findByRequesterUsernameOrderByCreatedAtDesc(u.username());}
 @Transactional public WorkflowRequest create(String s,WorkflowCreateRequest in){var u=auth.require(s); String type=in.workflowType().trim().toUpperCase(); if(!Set.of("PROCUREMENT","ONBOARDING","SECONDARY").contains(type)) throw new IllegalArgumentException("Allowed workflow types: PROCUREMENT, ONBOARDING, SECONDARY"); if(type.equals("ONBOARDING")&&!Set.of("HR","ADMIN").contains(u.role())) throw new IllegalArgumentException("Only HR or Admin can create onboarding requests"); if(type.equals("PROCUREMENT")&&!u.role().equals("ADMIN")) throw new IllegalArgumentException("Only System Admin can create procurement requests"); if(type.equals("SECONDARY")&&!Set.of("EMPLOYEE","ADMIN").contains(u.role())) throw new IllegalArgumentException("Only employees can create secondary hardware requests"); String employeeName=isBlank(in.employeeName())?u.displayName():in.employeeName().trim(); String employeeUsername=null; if(type.equals("ONBOARDING") && u.role().equalsIgnoreCase("HR")){ employeeUsername=ensureOnboardingEmployee(employeeName,in.employeeId(),in.department()); } String no="REQ-"+System.currentTimeMillis()%1000000; String items=itemsJson(in.items()); WorkflowRequest r=new WorkflowRequest(no,type,u.username(),u.displayName(),employeeName,in.employeeId(),isBlank(in.department())?u.department():in.department(),in.assetType().trim().toUpperCase(),in.reason(),in.priority(),in.requiredDate(),items,in.estimatedCostMinor(),in.currency(),in.budgetMinor()); r.setAccountUsername(employeeUsername); r.move(type.equals("ONBOARDING")?"UNDER_REVIEW":"APPROVAL_PENDING",type.equals("SECONDARY")?"MANAGER_APPROVAL":type.equals("PROCUREMENT")?"FINANCE_BUDGET":"ADMIN_REVIEW"); requests.save(r); approvals.save(new WorkflowApproval(r,type.equals("SECONDARY")?"MANAGER":type.equals("PROCUREMENT")?"FINANCE":"VP")); audit.save(new AuditLog(u.username(),"WORKFLOW_REQUEST_CREATED","WORKFLOW_REQUEST",r.getId().toString(),type+" "+r.getRequestNo())); notifyRole(type.equals("SECONDARY")?"manager":type.equals("PROCUREMENT")?"finance":"vp","New workflow request",r.getRequestNo()+" requires approval."); return r;}
 private String ensureOnboardingEmployee(String employeeName,String employeeId,String department){ String base=employeeName.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+",".").replaceAll("^\\.|\\.$",""); if(base.isBlank()) throw new IllegalArgumentException("Unable to create employee username from employee name"); String username=base; SessionAuthService.User existing=auth.getUser(username); if(existing!=null && !existing.role().equalsIgnoreCase("EMPLOYEE")){ username=base+(isBlank(employeeId)?"":employeeId.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]","")); existing=auth.getUser(username); } if(existing==null){ auth.createUserAccount(username,"employee123","EMPLOYEE",employeeName,null,isBlank(department)?"":department); } else if(!existing.role().equalsIgnoreCase("EMPLOYEE")){ throw new IllegalArgumentException("Username already exists for a non-employee account: "+username); } return username; }
 @Transactional public WorkflowRequest delegateToVp(String s,UUID id){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getWorkflowType().equals("ONBOARDING")||!r.getStage().equals("ADMIN_REVIEW")) throw new IllegalArgumentException("Onboarding request is not ready for VP delegation"); r.move("APPROVAL_PENDING","VP_APPROVAL"); requests.save(r); notifyRole("vp","Onboarding approval required",r.getRequestNo()+" for "+r.getEmployeeName()); audit.save(new AuditLog(u.username(),"DELEGATED_TO_VP","WORKFLOW_REQUEST",id.toString(),r.getRequestNo())); return r;}
 @Transactional public WorkflowRequest approve(String s,UUID id,DecisionRequest in){var u=auth.require(s); WorkflowRequest r=get(id); String role=r.getStage().equals("MANAGER_APPROVAL")?"MANAGER":r.getStage().equals("FINANCE_BUDGET")?"FINANCE":"VP"; if(!u.role().equalsIgnoreCase(role)&&!u.role().equalsIgnoreCase("ADMIN")) throw new IllegalArgumentException("Only "+role+" can approve this request"); if(role.equals("FINANCE") && r.getEstimatedCostMinor()!=null && r.getBudgetMinor()!=null && r.getEstimatedCostMinor()>r.getBudgetMinor()) throw new IllegalArgumentException("Estimated cost exceeds the submitted budget. Return the request for revision."); WorkflowApproval a=approvals.findByRequestId(id).stream().filter(x->x.getDecision().equals("PENDING")&&x.getApproverRole().equals(role)).findFirst().orElseThrow(()->new IllegalArgumentException("No pending "+role+" approval")); a.decide(u.username(),"APPROVED",in==null?null:in.comments()); approvals.save(a); if(r.getWorkflowType().equals("PROCUREMENT")&&role.equals("FINANCE")){r.setBudget(r.getEstimatedCostMinor());r.move("APPROVAL_PENDING","VP_APPROVAL"); approvals.save(new WorkflowApproval(r,"VP")); notifyRole("vp","VP approval required",r.getRequestNo());} else if(role.equals("VP")){r.move("IN_PROGRESS","INVENTORY"); notifyRole("admin","Inventory action required",r.getRequestNo());} else {r.move("IN_PROGRESS","INVENTORY"); notifyRole("admin","Inventory action required",r.getRequestNo());} requests.save(r); audit.save(new AuditLog(u.username(),"WORKFLOW_APPROVED","WORKFLOW_REQUEST",id.toString(),role)); return r; }
 @Transactional public WorkflowRequest returnForRevision(String s,UUID id,DecisionRequest in){var u=auth.requireRole(s,"FINANCE"); WorkflowRequest r=get(id); if(!r.getStage().equals("FINANCE_BUDGET")) throw new IllegalArgumentException("Only Finance budget requests can be returned"); r.move("UNDER_REVIEW","FINANCE_BUDGET"); requests.save(r); notifications.save(new Notification(r.getRequesterUsername(),"Request returned for revision",r.getRequestNo()+" needs budget/request revision.")); audit.save(new AuditLog(u.username(),"REQUEST_RETURNED_FOR_REVISION","WORKFLOW_REQUEST",id.toString(),in==null?"Budget revision required":in.comments())); return r;}
 @Transactional public WorkflowRequest reject(String s,UUID id,DecisionRequest in){var u=auth.require(s); WorkflowRequest r=get(id); String role=r.getStage().equals("MANAGER_APPROVAL")?"MANAGER":r.getStage().equals("FINANCE_BUDGET")?"FINANCE":"VP"; if(!u.role().equalsIgnoreCase(role)&&!u.role().equalsIgnoreCase("ADMIN")) throw new IllegalArgumentException("Only "+role+" can reject this request"); String reason=in==null||isBlank(in.comments())?"Request rejected":in.comments(); r.reject(reason); requests.save(r); notifications.save(new Notification(r.getRequesterUsername(),"Request rejected",r.getRequestNo()+" was rejected: "+reason)); audit.save(new AuditLog(u.username(),"WORKFLOW_REJECTED","WORKFLOW_REQUEST",id.toString(),reason)); return r; }
 @Transactional public WorkflowRequest reserve(String s,UUID id,ReserveRequest in){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!Set.of("IN_PROGRESS","APPROVED").contains(r.getStatus())||!r.getStage().equals("INVENTORY")) throw new IllegalArgumentException("Request is not ready for inventory selection"); if(in.ids().isEmpty()) throw new IllegalArgumentException("At least one asset must be selected"); for(UUID aid:in.ids()){var a=assets.findById(aid).orElseThrow(()->new IllegalArgumentException("Asset not found: "+aid)); if(a.getStatus()!=AssetStatus.IN_STOCK) throw new IllegalArgumentException("Asset is not In Stock: "+a.getAssetTag()); if(reservations.existsByAssetIdAndStatus(a.getId(),"RESERVED")) throw new IllegalArgumentException("Asset is already reserved: "+a.getAssetTag()); reservations.save(new AssetReservation(id,a.getId(),r.getEmployeeName())); audit.save(new AuditLog(u.username(),"ASSET_RESERVED","WORKFLOW_REQUEST",id.toString(),a.getAssetTag())); } r.move("IN_PROGRESS","RESERVED"); requests.save(r); return r; }
 @Transactional public WorkflowRequest allocate(String s,UUID id){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getStage().equals("RESERVED")) throw new IllegalArgumentException("Reserve an asset before allocation"); var list=reservations.findByRequestId(id).stream().filter(x->x.getStatus().equals("RESERVED")).toList(); if(list.isEmpty()) throw new IllegalArgumentException("No reserved asset"); for(AssetReservation res:list){var a=assets.findById(res.getAssetId()).orElseThrow(); assetService.updateStatus(a.getId(),"ASSIGNED",u.username(),r.getEmployeeName()); res.allocate(); reservations.save(res); audit.save(new AuditLog(u.username(),"ASSET_ALLOCATED","WORKFLOW_REQUEST",id.toString(),a.getAssetTag()));} r.move("COMPLETED","HANDOVER"); requests.save(r); notifications.save(new Notification(r.getRequesterUsername(),"Assets allocated",r.getRequestNo()+" has been allocated.")); return r; }
 @Transactional public WorkflowRequest createPo(String s,UUID id,PurchaseOrderRequest in){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getWorkflowType().equals("PROCUREMENT")||!r.getStage().equals("INVENTORY")) throw new IllegalArgumentException("Procurement request is not ready for PO"); String no="PO-"+(System.currentTimeMillis()%1000000); PurchaseOrder po=pos.save(new PurchaseOrder(id,no,in.vendorName(),in.amountMinor(),in.currency())); r.setVendor(in.vendorName());r.setPo(no);r.move("IN_PROGRESS","PURCHASE_ORDER");requests.save(r);audit.save(new AuditLog(u.username(),"PURCHASE_ORDER_CREATED","WORKFLOW_REQUEST",id.toString(),no));return r;}
 @Transactional public WorkflowRequest receive(String s,UUID id,GoodsReceiptRequest in){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getStage().equals("PURCHASE_ORDER")) throw new IllegalArgumentException("Purchase order must be created first"); PurchaseOrder po=pos.findByRequestId(id).orElseThrow(); String no="GRN-"+(System.currentTimeMillis()%1000000); grns.save(new GoodsReceipt(id,po.getId(),no,in.receivedQuantity()==null?1:in.receivedQuantity(),in.condition(),in.notes())); r.setGrn(no);r.move("IN_PROGRESS","INSPECTION");requests.save(r);audit.save(new AuditLog(u.username(),"GOODS_RECEIVED","WORKFLOW_REQUEST",id.toString(),no));return r;}
 @Transactional public WorkflowRequest inspect(String s,UUID id){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getStage().equals("INSPECTION")) throw new IllegalArgumentException("Request is not awaiting inspection"); GoodsReceipt g=grns.findByRequestId(id).orElseThrow();g.inspect();grns.save(g);r.move("COMPLETED","ASSET_READY");requests.save(r);audit.save(new AuditLog(u.username(),"ASSET_INSPECTED","WORKFLOW_REQUEST",id.toString(),"Goods inspected and ready for asset registration"));return r;}
 @Transactional public WorkflowRequest registerAsset(String s,UUID id,RegisterAssetRequest in){var u=auth.requireRole(s,"ADMIN"); WorkflowRequest r=get(id); if(!r.getStage().equals("ASSET_READY")) throw new IllegalArgumentException("Goods must be inspected before asset registration"); Asset asset=assets.save(new Asset(in.assetTag(),in.type(),in.make(),in.model(),in.serialNumber(),in.purchaseDate(),in.warrantyExpiry(),in.costMinor(),in.currency()==null?"INR":in.currency(),in.condition(),in.notes())); r.move("COMPLETED","ASSET_REGISTERED"); requests.save(r); audit.save(new AuditLog(u.username(),"ASSET_REGISTERED_FROM_GRN","WORKFLOW_REQUEST",id.toString(),asset.getAssetTag())); return r;}
 @Transactional public WorkflowRequest close(String s,UUID id){var u=auth.requireRole(s,"ADMIN");WorkflowRequest r=get(id);if(!r.getStatus().equals("COMPLETED")&&!r.getStatus().equals("REJECTED"))throw new IllegalArgumentException("Only completed or rejected requests can be closed");r.close();requests.save(r);audit.save(new AuditLog(u.username(),"REQUEST_CLOSED","WORKFLOW_REQUEST",id.toString(),r.getRequestNo()));return r;}
 @Transactional public MaintenanceTicket createMaintenance(String s,MaintenanceCreateRequest in){var u=auth.require(s);var a=assets.findById(in.assetId()).orElseThrow(()->new IllegalArgumentException("Asset not found"));if("EMPLOYEE".equals(u.role()) && (a.getAssignedTo()==null || !a.getAssignedTo().equalsIgnoreCase(u.displayName()))) throw new IllegalArgumentException("You can report issues only for assets assigned to you");assetService.updateStatus(a.getId(),"IN_REPAIR",u.username(),a.getAssignedTo());String no="REQ-M-"+(System.currentTimeMillis()%1000000);WorkflowRequest r=new WorkflowRequest(no,"MAINTENANCE",u.username(),u.displayName(),a.getAssignedTo()==null?u.displayName():a.getAssignedTo(),null,u.department(),a.getType(),in.issueDescription(),"HIGH",null,"[]",null,"INR",null);r.setMaintenanceRequest();requests.save(r);MaintenanceTicket t=new MaintenanceTicket(a.getId(),u.username(),in.issueDescription());t.setRequestId(r.getId());maintenance.save(t);audit.save(new AuditLog(u.username(),"MAINTENANCE_REPORTED","WORKFLOW_REQUEST",r.getId().toString(),in.issueDescription()));return t;}
 @Transactional public MaintenanceTicket diagnose(String s,UUID id,String diagnosis,boolean repairable){var u=auth.requireRole(s,"ADMIN");var t=maintenance.findById(id).orElseThrow();t.diagnose(diagnosis,repairable);maintenance.save(t);audit.save(new AuditLog(u.username(),"MAINTENANCE_DIAGNOSED","MAINTENANCE_TICKET",id.toString(),repairable?"REPAIR":"REPLACEMENT"));return t;}
 @Transactional public MaintenanceTicket replaceMaintenance(String s,UUID id,UUID replacementAssetId){var u=auth.requireRole(s,"ADMIN");var t=maintenance.findById(id).orElseThrow();if(!"REPLACEMENT".equals(t.getStatus())) throw new IllegalArgumentException("Ticket is not in replacement state");var old=assets.findById(t.getAssetId()).orElseThrow();var replacement=assets.findById(replacementAssetId).orElseThrow();if(replacement.getStatus()!=AssetStatus.IN_STOCK) throw new IllegalArgumentException("Replacement asset must be In Stock");assetService.updateStatus(old.getId(),"RETIRED",u.username(),null);assetService.updateStatus(replacement.getId(),"ASSIGNED",u.username(),old.getAssignedTo());t.resolve("Replacement asset assigned: "+replacement.getAssetTag());maintenance.save(t);if(t.getRequestId()!=null){WorkflowRequest r=get(t.getRequestId());r.move("COMPLETED","HANDOVER");r.close();requests.save(r);}audit.save(new AuditLog(u.username(),"ASSET_REPLACED","MAINTENANCE_TICKET",id.toString(),old.getAssetTag()+" -> "+replacement.getAssetTag()));return t;}
 @Transactional public MaintenanceTicket resolve(String s,UUID id,String resolution){var u=auth.requireRole(s,"ADMIN");var t=maintenance.findById(id).orElseThrow();var a=assets.findById(t.getAssetId()).orElseThrow();t.resolve(resolution);maintenance.save(t);assetService.updateStatus(a.getId(),"ASSIGNED",u.username(),a.getAssignedTo());if(t.getRequestId()!=null){WorkflowRequest r=get(t.getRequestId());r.move("COMPLETED","HANDOVER");requests.save(r);r.close();requests.save(r);}audit.save(new AuditLog(u.username(),"MAINTENANCE_RESOLVED","MAINTENANCE_TICKET",id.toString(),resolution));return t;}
 public List<MaintenanceTicket> maintenance(String s){auth.requireRole(s,"ADMIN");return maintenance.findAllByOrderByCreatedAtDesc();}
 private WorkflowRequest get(UUID id){return requests.findById(id).orElseThrow(()->new IllegalArgumentException("Workflow request not found: "+id));}
 private void notifyRole(String role,String title,String msg){usernames(role).forEach(u->notifications.save(new Notification(u,title,msg)));}
 private List<String> usernames(String role){return auth.allUsers().stream().filter(x->x.role().equalsIgnoreCase(role)).map(SessionAuthService.User::username).toList();}
 private boolean isBlank(String s){return s==null||s.isBlank();}
 private String itemsJson(List<String> items){ if(items==null||items.isEmpty()) return "[]"; StringBuilder b=new StringBuilder("["); for(int i=0;i<items.size();i++){ if(i>0)b.append(","); String v=items.get(i)==null?"":items.get(i); b.append("\"").append(v.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")).append("\""); } return b.append("]").toString(); }
}
